function initUpdateAddress(e,t,n){e.preventDefault();const r=document.querySelectorAll(t);r.forEach((e=>{if(e.classList.contains("active")){e.classList.remove("active")}}));const a=e.currentTarget.closest(t);a.classList.add("active");let o=a.querySelector(".id").innerText;let s=a.querySelector(".receiver").innerText;let c=a.querySelector(".phone").innerText;let i=a.querySelector(".street").innerText;let d=a.querySelector(".village").innerText;let l=a.querySelector(".district").innerText;let u=a.querySelector(".province").innerText;const f=document.querySelector(n);const m=f.querySelectorAll("input");m.forEach((e=>{if(e.name=="id")e.value=o;else if(e.name=="receiver")e.value=s;else if(e.name=="phone")e.value=c;else if(e.name=="street")e.value=i;else if(e.name=="village")e.value=d;else if(e.name=="district")e.value=l;else if(e.name=="province")e.value=u;else if(e.name=="action")e.value="updateAddress"}));f.querySelector(".edit-title").innerText="Cập nhật địa chỉ";document.querySelector("#address-form-container").classList.add("active")}function initAddAddress(e){const t=document.querySelector(e);const n=t.querySelectorAll("input");n.forEach((e=>{e.value=""}));t.querySelectorAll('input[name="action"]').value="addAddress";t.querySelector(".edit-title").innerText="Thêm địa chỉ";document.querySelector("#address-form-container").classList.add("active")}function updateAddressAjax(e,t,n,r,a,o,s,c){return new Promise(((i,d)=>{$.ajax({url:"profile",type:"GET",dataType:"json",data:{a:e,id:t,receiver:n,phone:r,detail:a,village:o,district:s,province:c},success:function(e){i(e);cancelEdit("#editAddressForm");showSuccessToast("Cập nhật địa chỉ thành công","#toast-header")},error:function(e){d(e)}})}))}function addAddressAjax(e,t,n,r,a,o,s,c){return new Promise(((i,d)=>{$.ajax({url:"profile",type:"GET",dataType:"json",data:{a:e,id:t,receiver:n,phone:r,detail:a,village:o,district:s,province:c},success:function(e){i(e);cancelEdit("#editAddressForm");showSuccessToast("Thêm địa chỉ thành công","#toast-header")},error:function(e){d(e)}})}))}function cancelEdit(e){const t=document.querySelector(e);const n=t.querySelectorAll("input");n.forEach((e=>{e.value="";if(e.name=="action")e.value="addAddress"}));t.querySelector(".edit-title").innerText="Thêm địa chỉ";if(document.querySelector("#address-form-container.active")){document.querySelector("#address-form-container").classList.remove("active")}}function initDeleteAddress(e,t,n,r){const a=document.querySelectorAll(t);a.forEach((e=>{if(e.classList.contains("active")){e.classList.remove("active")}}));const o=e.currentTarget.closest(t);o.classList.add("active");let s=o.querySelector(".id").innerText;let c=o.querySelector(".receiver").innerText;let i=o.querySelector(".phone").innerText;let d=o.querySelector(".address").innerText;const l=o.closest(n);const u=l.querySelector(r);u.querySelector(".id").innerText=s;u.querySelector(".receiver").innerText=c;u.querySelector(".phone").innerText=i;u.querySelector(".address").innerText=d;u.classList.add("active")}function deleteAddressAjax(e){return new Promise(((t,n)=>{$.ajax({url:"profile",type:"GET",dataType:"json",data:{a:"deleteAddress",id:e},success:function(e){t(e);$(".address-confirm").removeClass("active");showSuccessToast("Xóa địa chỉ thành công","#toast-header")},error:function(e){n(e)}})}))}function cancelDelete(e,t){e.currentTarget.closest(t).classList.remove("active")}function initUpdateInfo(e,t){const n=e.currentTarget.closest(t);const r=n.querySelectorAll("input");r.forEach((e=>{e.removeAttribute("readonly");if(e.name=="dateIn")e.readOnly=true;if(e.name=="email")e.readOnly=true}));const a=n.querySelectorAll('input[type="radio"]');a.forEach((e=>{e.disabled=false}));n.querySelector(".update-action").style.display="none";n.querySelector(".edit-title").style.display="block";n.querySelector(".btn-edit-container").style.display="flex"}function cancelEditInfo(e){const t=document.querySelector(e);const n=t.querySelectorAll("input");n.forEach((e=>{e.setAttribute("readonly",true)}));const r=t.querySelectorAll('input[type="radio"]');r.forEach((e=>{e.disabled=true}));t.querySelector(".update-action").style.display="flex";t.querySelector(".edit-title").style.display="none";t.querySelector(".btn-edit-container").style.display="none"}function initChangePwd(e,t){e.preventDefault();document.querySelector(t).classList.add("active")}function cancelChangePwd(e){document.querySelector(e).classList.remove("active")}function manageAddress(e){e.preventDefault();document.querySelector(".address-modal").classList.add("active");getAddressList().then((function(e){renderAddressList(e)})).catch((function(e){console.error("Có lỗi khi lấy danh sách địa chỉ:",e);$("#address-container").html("<p>Không thể tải danh sách địa chỉ.</p>")}))}function manageProfile(e){e.preventDefault();document.querySelector(".info-modal").classList.add("active");if(document.querySelector("#edit-pwd-form-container").classList.contains("active")){document.querySelector("#edit-pwd-form-container").classList.remove("active")}getUserInfo().then((function(e){renderUserInfo(e)})).catch((function(e){}));cancelEditInfo("#editInfoForm")}function loadUserInfo(){$.ajax({type:"post",url:"profile",data:{a:"info"},success:function(e){$('#editInfoForm input[name="name"]').val(e.name);$('#editInfoForm input[name="email"]').val(e.email);$('#editInfoForm input[name="phone"]').val(e.phone);$('#editInfoForm input[name="birthday"]').val(e.dob);const t=document.querySelectorAll('#editInfoForm input[name="gender"]');t.forEach((t=>{if(t.value==e.gender)t.checked=true;else t.checked=false}))},error:function(e){console.error("Error during querying address: ",e)}})}function openHeaderModal(e){const t=document.querySelector(e);t.classList.add("active")}function getUserInfo(){return new Promise(((e,t)=>{$.ajax({url:"profile?a=info",type:"GET",dataType:"json",success:function(t){e(t)},error:function(e){t(e)}})}))}function renderUserInfo(e){$('#editInfoForm input[name="name"]').val(e.name);$('#editInfoForm input[name="email"]').val(e.email);$('#editInfoForm input[name="phone"]').val(e.phone);$('#editInfoForm input[name="birthday"]').val(e.dob);const t=document.querySelectorAll('#editInfoForm input[name="gender"]');t.forEach((t=>{if(t.value==e.gender)t.checked=true;else t.checked=false;t.disabled=true}));var n=e.script;if(n!==undefined){$("#header-response").html(n)}}function getAddressList(){return new Promise(((e,t)=>{$.ajax({url:"profile?a=address",type:"GET",dataType:"json",success:function(t){e(t)},error:function(e){t(e)}})}))}function renderAddressList(e){const t=$("#address-container");t.empty();e.forEach((function(e){const n=`\n            <div class="address-item">\n                <div class="flex-roww" style="justify-content: space-between; align-items: start">\n                    <div class="address-info">\n                        <p><span class="receiver">${e.receiver}</span> | <span class="phone">${e.phone}</span></p>\n                        <p class="id" hidden="">${e.id}</p>\n                        <p style="margin-top: 5px">Địa chỉ:</p>\n                        <div>\n                            <p class="address" style="margin-left: 10px;">\n                                <span class="street">${e.detail}</span> - \n                                <span class="village">${e.village}</span> - \n                                <span class="district">${e.district}</span> - \n                                <span class="province">${e.province}</span>\n                            </p>\n                        </div>\n                    </div>\n                    <div class="flex-coll update-action">\n                        <i class="bi bi-pencil-square btn-edit" onclick="initUpdateAddress(event, '.address-item', '#editAddressForm')"></i>\n                        <i class="bi bi-trash btn-delete" onclick="initDeleteAddress(event, '.address-item', '.modall', '.address-confirm')"></i>\n                    </div>\n                </div>\n                <div class="seperate-horizontal-90"></div>\n            </div>\n        `;t.append(n)}))}function openElement(e){document.querySelector(e).classList.add("active");document.querySelector(e).style.display="block"}function closeElement(e){document.querySelector(e).classList.remove("active")}document.addEventListener("DOMContentLoaded",(function(){const e=document.querySelector("#editInfoForm");e.addEventListener("submit",(function(e){e.preventDefault();var t=new FormData(this);let n=t.get("name");let r=t.get("email");let a=t.get("gender");let o=t.get("phone");let s=t.get("birthday");let c=t.get("dateIn");let i=t.get("a");saveUpdateInfo(i,n,r,a,o,s,c).then((function(e){renderUserInfo(e)})).catch((function(e){}))}));document.querySelector("#editPasswordForm").addEventListener("submit",(function(e){e.preventDefault();var t=new FormData(document.querySelector("#editPasswordForm"));var n=t.get("action");var r=t.get("currentPassword");var a=t.get("password");var o=t.get("repassword");changePwd(n,r,a,o)}))}));function saveUpdateInfo(e,t,n,r,a,o,s){return new Promise(((c,i)=>{$.ajax({type:"post",url:"profile",dataType:"json",data:{a:e,name:t,email:n,gender:r,phone:a,birthday:o,dateIn:s},success:function(e){c(e)},error:function(e){i(e)}})}))}function changePwd(e,t,n,r){const a=/^(?=.*[a-z]).{8,}$/;if(!a.test(n)){wrongNewPwd("#editPasswordForm","* Mật khẩu phải ít nhất 8 ký tự, gồm chữ và số")}else if(n!=r){wrongNewPwd("#editPasswordForm","Mật khẩu không trùng khớp")}else{clearError("#editPasswordForm");$.ajax({url:"profile",method:"POST",data:{a:e,currentPassword:t,password:n,repassword:r},success:function(e){$("#header-response").html(e)}})}}function showMenu(){document.querySelector(".header_bottom").classList.add("active");document.querySelector(".overlay_mob").classList.add("active")}function hideMenu(){document.querySelector(".header_bottom").classList.remove("active");document.querySelector(".overlay_mob").classList.remove("active")}